import os, re, json

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
demo_input = G['Demo pair 1 input']
test_input = G['Test input']

def count_isolated_by_value(grid, target_val):
    """Count how many cells with value target_val have no same-value neighbors"""
    h, w = len(grid), len(grid[0])
    isolated = 0
    total = 0
    for i in range(h):
        for j in range(w):
            if grid[i][j] != target_val:
                continue
            total += 1
            has_same = False
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0:
                        continue
                    ni, nj = i + di, j + dj
                    if 0 <= ni < h and 0 <= nj < w:
                        if grid[ni][nj] == target_val:
                            has_same = True
                            break
                if has_same:
                    break
            if not has_same:
                isolated += 1
    return isolated, total

print("=== Demo input ===")
iso5, tot5 = count_isolated_by_value(demo_input, 5)
iso7, tot7 = count_isolated_by_value(demo_input, 7)
print(f"Value 5: {iso5} isolated / {tot5} total")
print(f"Value 7: {iso7} isolated / {tot7} total")

print("\n=== Test input ===")
iso5, tot5 = count_isolated_by_value(test_input, 5)
iso6, tot6 = count_isolated_by_value(test_input, 6)
print(f"Value 5: {iso5} isolated / {tot5} total")
print(f"Value 6: {iso6} isolated / {tot6} total")

