import os, re, json
from collections import Counter

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
test_input = G['Test input']

# Rule confirmed: minority value becomes majority value, everything else becomes 0
all_vals = []
for row in test_input:
    for v in row:
        all_vals.append(v)
ctest = Counter(all_vals)

minority_val = min(ctest.keys(), key=lambda x: ctest[x])
majority_val = max(ctest.keys(), key=lambda x: ctest[x])

def apply_rule(grid, min_v, maj_v):
    result = []
    for row in grid:
        new_row = []
        for v in row:
            if v == min_v:
                new_row.append(maj_v)
            else:
                new_row.append(0)
        result.append(new_row)
    return result

test_output = apply_rule(test_input, minority_val, majority_val)

print(json.dumps(test_output))
